use std::cell::RefCell;
use std::cmp::max;
use std::rc::{Rc, Weak};

fn bostree_balance_internal(node: &Rc<RefCell<BOSNode>>) -> i32 {
    let n = node.borrow();
    let left_depth = n.left_child_node.as_ref().map_or(0, |l| l.borrow().depth + 1);
    let right_depth = n.right_child_node.as_ref().map_or(0, |r| r.borrow().depth + 1);
    right_depth as i32 - left_depth as i32
}

fn rotate_right(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    // Get P's left child (L)
    let l = p.borrow().left_child_node.clone().unwrap();

    // Update P's parent to point to L
    let p_parent_weak = p.borrow().parent_node.clone();
    if let Some(ref pw) = p_parent_weak {
        let parent = pw.upgrade().unwrap();
        let is_left = parent.borrow().left_child_node.as_ref()
            .map_or(false, |lc| Rc::ptr_eq(lc, p));
        drop(parent); // release parent borrow
        let parent = p_parent_weak.as_ref().unwrap().upgrade().unwrap();
        if is_left {
            parent.borrow_mut().left_child_node = Some(l.clone());
        } else {
            parent.borrow_mut().right_child_node = Some(l.clone());
        }
    } else {
        tree.root_node = Some(l.clone());
    }

    // L->parent_node = P->parent_node
    l.borrow_mut().parent_node = p_parent_weak;

    // P->left_child_node = L->right_child_node
    // P->left_child_count = L->right_child_count
    let l_right = l.borrow().right_child_node.clone();
    let l_right_count = l.borrow().right_child_count;
    p.borrow_mut().left_child_node = l_right.clone();
    p.borrow_mut().left_child_count = l_right_count;

    // If L's right child exists, set its parent to P
    if let Some(ref lr) = l_right {
        lr.borrow_mut().parent_node = Some(Rc::downgrade(p));
    }

    // P->depth = max(left_depth, right_depth)
    {
        let p_borrow = p.borrow();
        let left_depth = p_borrow.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let right_depth = p_borrow.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        drop(p_borrow);
        p.borrow_mut().depth = max(left_depth, right_depth);
    }

    // P->parent_node = L
    p.borrow_mut().parent_node = Some(Rc::downgrade(&l));

    // L->right_child_node = P
    l.borrow_mut().right_child_node = Some(p.clone());

    // L->right_child_count = P->left_child_count + P->right_child_count + 1
    {
        let p_left_count = p.borrow().left_child_count;
        let p_right_count = p.borrow().right_child_count;
        l.borrow_mut().right_child_count = p_left_count + p_right_count + 1;
    }

    // L->depth = max(left_depth, right_depth)
    {
        let l_borrow = l.borrow();
        let left_depth = l_borrow.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let right_depth = l_borrow.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        drop(l_borrow);
        l.borrow_mut().depth = max(left_depth, right_depth);
    }

    l
}
